Generation constructs valid scalar strings without filtering, including delimiters, empty strings, supplementary characters, and special object keys. Unique keys use the library’s [structured array generator](https://fast-check.dev/docs/core-blocks/arbitraries/composites/array/). Bounds limit CI cost; they are not contract limits.

```diff
diff --git a/test/query-record.property.test.ts b/test/query-record.property.test.ts
new file mode 100644
--- /dev/null
+++ b/test/query-record.property.test.ts
@@ -0,0 +1,62 @@
+import * as fc from 'fast-check';
+import { expect, it } from 'vitest';
+import { decodeRecord, encodeRecord } from '../src/query-record';
+
+const scalar = fc.oneof(
+  fc.integer({ min: 0, max: 0xd7ff }),
+  fc.integer({ min: 0xe000, max: 0x10ffff }),
+  fc.constantFrom(0, 0x26, 0x3d, 0x25, 0xd7ff, 0xe000, 0x10000, 0x10ffff),
+).map((point) => String.fromCodePoint(point));
+
+const scalarString = fc.oneof(
+  fc.constantFrom('', '&', '=', '%', '+', '__proto__', 'constructor', 'é', 'e\u0301'),
+  fc.array(scalar, { maxLength: 64 }).map((characters) => characters.join('')),
+);
+
+const records = fc.uniqueArray(fc.tuple(scalarString, scalarString), {
+  maxLength: 16,
+  selector: ([key]) => key,
+}).map((entries) => Object.fromEntries(entries) as Record<string, string>);
+
+function compareScalarStrings(left: string, right: string): number {
+  const a = Array.from(left, (character) => character.codePointAt(0)!);
+  const b = Array.from(right, (character) => character.codePointAt(0)!);
+  for (let index = 0; index < Math.min(a.length, b.length); index += 1) {
+    if (a[index] !== b[index]) return a[index] - b[index];
+  }
+  return a.length - b.length;
+}
+
+it('encodes records losslessly with keys in Unicode scalar order', () => {
+  fc.assert(
+    fc.property(records, (record) => {
+      const wire = encodeRecord(record);
+      const keys = wire === '' ? [] : wire.split('&').map((segment) => {
+        const separator = segment.indexOf('=');
+        expect(separator).toBeGreaterThanOrEqual(0);
+        return decodeURIComponent(segment.slice(0, separator));
+      });
+
+      expect(keys).toEqual(Object.keys(record).sort(compareScalarStrings));
+      expect(decodeRecord(wire)).toEqual(record);
+    }),
+    {
+      seed: 20260919,
+      numRuns: 300,
+      verbose: true,
+      examples: [
+        [{}],
+        [{ '': '' }],
+        [{ '&=%+': '\0é\u{10FFFF}', '': '=&%' }],
+        [Object.fromEntries([['__proto__', 'value'], ['constructor', '']])],
+        [{ '\uE000': '', '\u{10000}': '' }],
+        [Object.fromEntries(
+          Array.from({ length: 16 }, (_, index) => [
+            String(index),
+            '\u{10FFFF}'.repeat(64),
+          ]),
+        )],
+      ],
+    },
+  );
+}, 10_000);
```

