## Recommended test-only patch

```diff
diff --git a/test/query-record.test.ts b/test/query-record.test.ts
--- a/test/query-record.test.ts
+++ b/test/query-record.test.ts
@@ -10,4 +10,32 @@ describe('query records', () => {
   it('canonicalizes key order', () => {
     expect(canonicalize('name=Ada&city=Boston')).toBe('city=Boston&name=Ada');
   });
+
+  it('orders Unicode keys by code point', () => {
+    const keys = [
+      '',
+      '&',
+      '=',
+      '%',
+      '\u007f',
+      '\u0080',
+      '\ud7ff',
+      '\ue000',
+      '\u{10000}',
+      '\u{1f642}',
+      '\u{10ffff}',
+      'a\u{10000}',
+    ];
+    const compareCodePoints = (left: string, right: string): number => {
+      const leftPoints = Array.from(left, character => character.codePointAt(0)!);
+      const rightPoints = Array.from(right, character => character.codePointAt(0)!);
+      const sharedLength = Math.min(leftPoints.length, rightPoints.length);
+
+      for (let index = 0; index < sharedLength; index += 1) {
+        if (leftPoints[index] !== rightPoints[index])
+          return leftPoints[index] - rightPoints[index];
+      }
+      return leftPoints.length - rightPoints.length;
+    };
+
+    for (const left of keys) {
+      for (const right of keys) {
+        if (left === right) continue;
+        const encoded = encodeRecord({ [left]: 'left', [right]: 'right' });
+        const encodedKeys = encoded
+          .split('&')
+          .map(segment => decodeURIComponent(segment.slice(0, segment.indexOf('='))));
+        expect(encodedKeys, JSON.stringify({ left, right })).toEqual(
+          [left, right].sort(compareCodePoints),
+        );
+      }
+    }
+  });
 });
```

This is one bounded property test over Unicode boundary pairs. It uses only the public `encodeRecord` interface and an independent code-point comparator.

